export const getAnalyzeVideoUrl = () => {




  return `/api/sentinel/analyze`
}

/**
 * Runs real YOLO inference only when the model dependencies and weights are installed. Otherwise stores the upload and returns an explicit unavailable status without invented detections.
 * @summary Upload and analyze a traffic video
 */
export const analyzeVideo = async (videoAnalysisInput: VideoAnalysisInput, options?: Parameters<typeof customFetch>[1]): Promise<VideoAnalysisResult> => {
    const formData = new FormData();
formData.append(`video`, videoAnalysisInput.video);
formData.append(`cameraId`, videoAnalysisInput.cameraId);
if(videoAnalysisInput.location !== undefined) {
 formData.append(`location`, videoAnalysisInput.location);
 }
if(videoAnalysisInput.latitude !== undefined && videoAnalysisInput.latitude !== null) {
 formData.append(`latitude`, videoAnalysisInput.latitude.toString())
 }
if(videoAnalysisInput.longitude !== undefined && videoAnalysisInput.longitude !== null) {
 formData.append(`longitude`, videoAnalysisInput.longitude.toString())
 }
if(videoAnalysisInput.confidenceThreshold !== undefined) {
 formData.append(`confidenceThreshold`, videoAnalysisInput.confidenceThreshold.toString())
 }
if(videoAnalysisInput.suspiciousThreshold !== undefined) {
 formData.append(`suspiciousThreshold`, videoAnalysisInput.suspiciousThreshold.toString())
 }

  return customFetch<VideoAnalysisResult>(getAnalyzeVideoUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





